-- Разбор живого теста в реальном уроке вскрыл ещё две проблемы:
-- 1) сигнал, сработавший ДО того, как собран верный ответ, в ленте
--    оказывался НИЖЕ более поздних сообщений (сообщение об успехе) —
--    исправлено кодом (shared/lib/feedOrder.js/useSignalMessages.js),
--    правило ниже уточняет условие переиспользования ноды под сигнал;
-- 2) уточнение — граф должен быть логичным и без сигналов вовсе.
--
-- Обновляет rule_text предыдущего правила про переиспользование (уточнение,
-- не новая мысль) и добавляет одно новое правило.
--
-- Проверено на конфликт: rule_text уникальны, апдейт целится только в
-- правило БЕЗ уже добавленного уточнения (идемпотентно — повторный прогон
-- ничего не сломает, WHERE не найдёт уже обновлённую строку).
update public.lesson_rules
set rule_text = 'Прежде чем писать НОВУЮ ноду-сигнал — проверь, нет ли в уроке уже готовой ноды с подходящим объяснением (например, финальная ветка после трёх попыток той же самой ошибки, table_wrong/phrase_wrong/word_wrong). signals[].ref может ссылаться на ЛЮБУЮ ноду урока, в том числе уже стоящую в основном потоке графа — не обязательно строить отдельного «спутника» под каждый слот. Так подсказка не тратится впустую на дубль уже написанного текста, а ученик может увидеть то же объяснение раньше, бесплатно, при первой же ошибке, а не только выработав все три попытки. Компромисс: если ученик всё же дойдёт до этой ноды и обычным путём (все три попытки потрачены на ДРУГИХ слотах) — та же самая нода-объяснение может показаться в чате второй раз, это нормально, не баг, НО только если её текст естественно читается как самостоятельное объяснение в ОБОИХ случаях. Если содержимое ноды имеет смысл только как реакция на уже потраченные три попытки (например «Ну вот, теперь по порядку разберём…» — предполагает, что до этого уже были неудачные попытки) — такую ноду для сигнала не переиспользуй, напиши короткую отдельную подсказку.'
where rule_text like 'Прежде чем писать НОВУЮ ноду-сигнал%'
  and rule_text not like '%в ОБОИХ случаях%';

insert into public.lesson_rules (rule_text, sort_order, category)
select
  'Граф урока обязан оставаться логичным и понятным САМ ПО СЕБЕ, даже если ни один сигнал ни разу не сработает — сигналы это необязательная, «бесплатная» надстройка поверх обычного потока, а не замена ему. Не экономь на responseWrong или финальной ветке (table_wrong/phrase_wrong/word_wrong) в расчёте на то, что сигнал «и так объяснит» — ошибка ученика может не совпасть ни с одним назначенным слотом, или ученик вовсе не встретит сигнал (например, при повторном прохождении сработает другая последовательность ошибок). Основная цепочка обязана давать полноценное объяснение сама по себе, независимо от того, срабатывали сигналы или нет.',
  181,
  'principle'
where not exists (
  select 1 from public.lesson_rules
  where rule_text like 'Граф урока обязан оставаться логичным и понятным САМ ПО СЕБЕ%'
);
